「原因」（結果を引き起こすもと）／「理由」（そうする根拠、より主観を含む）
「進歩」（よい方向への変化）／「変化」（よい悪いを問わない変わり方）
「習慣」（個人の繰り返す行動）／「風習」（地域・集団の伝統的な行い）

