        body: `案内文・お知らせは、学校行事や地域のイベントなどを知らせる実用文です。5W1H（いつ・どこで・何を・誰が・なぜ・どのように）を正確に拾う練習をしましょう。

■ 5W1Hで整理する読み方
案内文を読むときは、次の項目を一つずつ確認しながら読みます。

| 項目 | 確認すること |
|------|-----------|
| When（いつ） | 開催日・締め切り・受付時間 |
| Where（どこで） | 会場・集合場所 |
| What（何を） | イベントの内容・持ち物 |
| Who（誰が） | 対象者（誰が参加できるか） |
| Why（なぜ） | 開催の目的・趣旨 |
| How（どのように） | 申し込み方法・参加費・注意事項 |

■ 「※」「注」の見落としに注意
案内文には、本文の下に「※」印で補足条件・例外が書かれていることがよくあります。
例）「参加費：無料　※ただし、教材費として300円が必要です。」
→ 「無料」だけを読んで「教材費」を見落とすと誤答になる。

■ 箇条書きの構造を整理する
案内文は情報を箇条書きでまとめることが多く、それぞれの項目の関係（並列か・条件付きか）を正確に読み取る必要があります。
例）
「持ち物：筆記用具、上履き　※雨天の場合は傘を各自ご用意ください。」
→ 「筆記用具・上履き」は常に必要、「傘」は雨天時のみという条件付きの持ち物。

★ ポイント：案内文の設問では「この案内から読み取れることとして正しいものを選びなさい」という形式が多い。選択肢と本文を一対一で照合し、「※」の例外条件まで含めて正誤を判断する。

⚠ 注意：案内文の日付・時間・場所などの「数字・固有名詞」は、選択肢問題で細かく変えられて出題されることが多い（例：「9時開始」を「9時30分開始」に変える）。本文の数字と選択肢の数字を必ず照合すること。`,
